\begin{tikzpicture}[font=\sffamily]
  % Axes
  \draw[->, thick] (0, -4.5) -- (0, 4) node[above] {$v$ / $\text{m s}^{-1}$};
  \draw[->, thick] (0, 0) -- (6.5, 0) node[right] {$t$ / s};

  % Origin
  \node[bottom left, font=\small] at (0, 0) {$0$};

  % Graph curve representing free fall, trampoline contact, and rebound
  % Fall to X: straight line from (0, -1.5) to X(1.5, -3.5)
  % Contact X to Y: curve from X(1.5, -3.5) to Y(3.0, 0)
  % Rebound Y to Z: straight line from Y(3.0, 0) to Z(4.5, 3)
  \draw[thick] (0.5, -1) coordinate (start) 
    -- (1.5, -3.5) coordinate (X)
    .. controls (2.2, -3.5) and (2.6, -1.5) .. (3.0, 0) coordinate (Y)
    -- (4.5, 3) coordinate (Z);

  % Labels for points X, Y, Z
  \node[above right, font=\small] at (X) {X};
  \node[above right, font=\small] at (Y) {Y};
  \node[above right, font=\small] at (Z) {Z};

  % Fig. 1.1 caption below
  \node[font=\sffamily] at (3.25, -5.2) {Fig. 1.1};

\end{tikzpicture}

